import {formatDate,dateInputValue,jalaliToISO} from './dates.js';import {parseAmount} from './search.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fa=n=>Number(n).toLocaleString('fa-IR');let reports=[],selected;
const statuses={open:'جدید',reviewing:'در حال بررسی',resolved:'رسیدگی‌شده',rejected:'ردشده'},kinds={price:'قیمت اشتباه',stock:'موجودی',details:'مشخصات',address:'آدرس',other:'سایر'};
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok){if(r.status===401){$('#dashboard').hidden=true;$('#loginPanel').hidden=false;$('#logout').hidden=true}throw Error(r.status===401?'رمز یا نشست معتبر نیست.':r.status===429?'تعداد درخواست زیاد است؛ یک دقیقه صبر کنید.':d.error==='invalid_observation'?'قیمت، فروشگاه، تاریخ و منبع استعلام را بررسی کنید.':'انجام عملیات ممکن نشد؛ دوباره تلاش کنید.')}return d}
async function action(fn,button){$('#message').textContent='در حال انجام…';if(button)button.disabled=true;try{await fn();$('#message').textContent='انجام شد.'}catch(e){$('#message').textContent=e.message}finally{if(button)button.disabled=false}}
const table=(heads,rows)=>rows.length?`<div class="data-table"><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">هنوز رکوردی ثبت نشده است.</div>';
async function refresh(){const d=await api('admin/summary');$('#loginPanel').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;$('#asOf').textContent='آخرین دریافت گزارش: '+formatDate(Date.now(),true)+(d.ai?' · سقف روزانهٔ مدل: '+fa(d.ai.limits.requests)+' درخواست / '+fa(d.ai.limits.reservedTokens)+' توکن رزروشده · مصرف رزرو: '+fa(d.ai.reservedTokens)+' · '+(d.ai.configured?'سرویس تنظیم شده':'سرویس مدل تنظیم نشده'):'');$('#metrics').innerHTML=[[d.dataset.products,'محصول در فهرست'],[d.dataset.shops,'فروشگاه'],[d.reports.open,'گزارش باز'],[d.snapshots.length,'ثبت نسخهٔ داده'],[d.ai?.requests||0,'درخواست مدل امروز'],[d.ai?.cacheHits||0,'پاسخ از حافظه']].map(([n,t])=>`<div class="metric"><strong>${fa(n)}</strong><span>${t}</span></div>`).join('');$('#snapshots').innerHTML=table(['زمان شمسی','محصول','دارای قیمت','تغییر','افزوده / حذف'],d.snapshots.slice().reverse().map(s=>[formatDate(s.at,true),fa(s.products),fa(s.priced),s.first?'ثبت اولیه':fa(s.changed),fa(s.added)+' / '+fa(s.removed)]));$('#changes').innerHTML=table(['محصول','قیمت قبلی','قیمت جدید','زمان ثبت'],d.changes.map(c=>[c.product,fa(c.previous),fa(c.price),formatDate(c.at,true)]));reports=(await api('admin/reports')).reports;renderReports()}
function renderReports(){const f=$('#reportFilter').value;const list=reports.filter(r=>f==='all'||r.status===f);$('#reportsList').innerHTML=list.length?list.map(r=>`<article class="report"><strong>${esc(r.title)}</strong><p>${esc(kinds[r.kind])} · ${esc(formatDate(r.at,true))} · ${esc(statuses[r.status])}</p><p>${esc(r.text)}</p><div class="report-actions"><select aria-label="وضعیت گزارش" data-status="${r.id}">${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select><textarea aria-label="پاسخ مدیر" maxlength="1000" data-reply="${r.id}" placeholder="پاسخ قابل مشاهده برای گزارش‌دهنده">${esc(r.reply)}</textarea><button data-save-report="${r.id}">ثبت پاسخ</button></div></article>`).join(''):'<div class="empty">گزارشی با این وضعیت ثبت نشده است.</div>'}
async function history(id){selected=id;const d=await api('history/'+encodeURIComponent(id));$('#productHistory').innerHTML=`<h3>${esc(d.product.title)}</h3><p>${esc(d.notice)}</p><h3>قیمت‌های موجود در دادهٔ اولیه</h3>`+table(['فروشگاه','قیمت (تومان)','تاریخ ثبت قیمت'],d.datasetOffers.map(o=>[o.shop,fa(o.price),formatDate(o.updated)]))+`<h3>تغییرات ثبت‌شده در سامانه</h3>`+table(['قبلی','جدید','زمان مشاهده'],d.changes.map(c=>[fa(c.previous),fa(c.price),formatDate(c.at,true)]))+`<h3>استعلام‌های مدیر</h3>`+table(['قیمت','منبع','زمان استعلام'],d.observations.map(o=>[fa(o.price),o.source,formatDate(o.observedAt,true)]));$('#observation').hidden=false;$('#observationShop').innerHTML=[...new Set(d.datasetOffers.map(o=>o.shop))].map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('');$('#observationDate').value=dateInputValue();$('#observationPrice').value=''}
$('#login').onsubmit=e=>{e.preventDefault();action(async()=>{await api('admin/login',{password:$('#password').value});$('#password').value='';await refresh()},e.submitter)};$('#logout').onclick=()=>action(async()=>{await api('admin/logout',{});location.reload()});$('#refresh').onclick=e=>action(refresh,e.currentTarget);$('#reportFilter').onchange=renderReports;$('#snapshot').onclick=e=>action(async()=>{await api('admin/snapshot',{});await refresh()},e.currentTarget);
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{for(const name of ['reports','history','updates'])$('#'+name).hidden=name!==b.dataset.panel;document.querySelectorAll('[data-panel]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.saveReport)action(async()=>{const id=b.dataset.saveReport;await api('admin/report',{id,status:$(`[data-status="${id}"]`).value,reply:$(`[data-reply="${id}"]`).value});await refresh()},b);if(b?.dataset.history)action(()=>history(b.dataset.history),b)});
$('#productSearch').onsubmit=e=>{e.preventDefault();action(async()=>{const d=await api('search?q='+encodeURIComponent($('#productQuery').value));$('#productResults').innerHTML=d.results.length?d.results.slice(0,10).map(r=>`<button data-history="${esc(r[0])}">${esc(r[1])} · ${fa(r[4])} تومان</button>`).join(''):'<p>نتیجه‌ای پیدا نشد.</p>'},e.submitter)};
$('#observation').onsubmit=e=>{e.preventDefault();action(async()=>{const date=jalaliToISO($('#observationDate').value,$('#observationTime').value);if(!date)throw Error('تاریخ شمسی معتبر وارد کنید.');await api('admin/observation',{product:selected,shop:$('#observationShop').value,price:parseAmount($('#observationPrice').value),observedAt:new Date(date+'+03:30').toISOString(),stock:$('#observationStock').value,source:$('#observationSource').value});await history(selected)},e.submitter)};
$('#exportReports').onclick=()=>{const csv=[['شناسه','محصول','نوع','وضعیت','زمان شمسی','متن','پاسخ'],...reports.map(r=>[r.id,r.title,kinds[r.kind],statuses[r.status],formatDate(r.at,true),r.text,r.reply])].map(row=>row.map(v=>'"'+String(v??'').replace(/^(?:\s*[=+@-]|[\t\r\n])/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='reports.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
refresh().catch(()=>{});
